debt:
%@: pullRequests(first: 5, states: [OPEN, MERGED, CLOSED], headRefName: "%@", %@) {
  nodes {
    number
    title
    state
    additions
    deletions
    isDraft
    reviewDecision
    mergeable
    mergeStateStatus
    url
    updatedAt
    headRefName
    baseRefName
    commits {
      totalCount
    }
    author {
      login
    }
    headRepository {
      name
      owner { login }
    }
    mergeQueueEntry {
      position
      estimatedTimeToMerge
      state
    }
    statusCheckRollup {
      contexts(first: 100) {
        nodes {
          ... on CheckRun {
            name
            status
            conclusion
            startedAt
            completedAt
            detailsUrl
          }
          ... on StatusContext {
            context
            state
            targetUrl
            createdAt
          }
        }
      }
    }
  }
}
